async (page) => {
  const results = [];
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  const check = (condition, message) => { if (!condition) throw new Error(message); results.push(message); };
  const snap = async () => await page.locator('body').ariaSnapshot();
  const capture = async name => { await page.screenshot({path:'F:/bike/output/playwright/ebike-hifi/'+name+'.png',fullPage:true}); };
  const nav = async hash => { await page.goto('http://127.0.0.1:8766/#'+hash); await snap(); };
  await page.setViewportSize({width:1440,height:1080});
  await nav('dashboard');
  await capture('01-admin-dashboard');
  await page.getByRole('button',{name:'TW-AS-20260909-0008',exact:true}).click(); await snap();
  await capture('03-case-detail');
  await page.getByRole('button',{name:'维修方案',exact:true}).click(); await snap();
  await capture('04-repair-plan');
  await page.getByRole('button',{name:'发运信息',exact:true}).click(); await snap();
  await capture('05-shipping-detail');
  await page.getByRole('button',{name:'旧件处理',exact:false}).click(); await snap();
  await capture('06-old-parts');
  await page.getByRole('button',{name:'变更记录',exact:true}).click(); await snap();
  await capture('07-case-history');
  await nav('cases'); await capture('02-case-list');
  await page.getByRole('textbox',{name:'案例搜索'}).fill('不存在的车架号');
  await page.getByRole('button',{name:'查询',exact:true}).click();
  check((await snap()).includes('没有找到符合条件的案例'),'案例搜索支持空结果');
  await page.getByRole('button',{name:'重置',exact:true}).click(); await snap();
  check(await page.getByRole('button',{name:'TW-AS-20260909-0008',exact:true}).count()===1,'重置恢复案例列表');
  await nav('shipments'); await capture('08-warehouse');
  await nav('dealers'); await capture('09-customers');
  await nav('vehicles'); await capture('10-vehicle');
  await nav('inventory'); await capture('11-inventory');
  await nav('production'); await capture('12-production');
  await nav('approvals');
  await page.getByRole('button',{name:'TW-AS-20260909-0011',exact:true}).click(); await snap();
  await page.getByRole('button',{name:'审批案例',exact:true}).click(); await snap();
  await capture('13-approval-dialog');
  await page.getByRole('combobox',{name:'审批结果'}).selectOption('reject');
  await page.getByRole('button',{name:'确认审批',exact:false}).click();
  check((await snap()).includes('拒绝或退回时必须填写原因'),'拒绝审批强制填写原因');
  await page.getByRole('combobox',{name:'审批结果'}).selectOption('approve');
  await page.getByRole('textbox',{name:'审批原因',exact:true}).fill('测试审批通过');
  await page.getByRole('button',{name:'确认审批',exact:false}).click(); await snap();
  check((await page.locator('h1').innerText()).includes('已审批'),'审批更新案例状态');
  await page.getByRole('button',{name:'发运信息',exact:true}).click(); await snap();
  await page.getByRole('button',{name:'登记发货',exact:true}).click(); await snap();
  await page.getByRole('textbox',{name:'物流单号',exact:true}).fill('DEMO-78352940');
  await page.getByRole('button',{name:'确认发货',exact:false}).click(); await snap();
  check((await page.locator('h1').innerText()).includes('已发货'),'发货更新案例和物流状态');
  await page.getByRole('combobox',{name:'切换原型角色'}).selectOption('customer'); await snap();
  await capture('14-customer-dashboard');
  check(!(await snap()).includes('Vélo Horizon'),'客户门户隐藏其他公司案例');
  await page.getByRole('button',{name:'申报售后案例',exact:true}).click(); await snap();
  await capture('15-new-case');
  await page.getByRole('button',{name:'填入演示车辆',exact:false}).click();
  await page.getByRole('button',{name:'保存草稿',exact:true}).click();
  await page.reload(); await snap();
  check(await page.locator('[name=frame]').inputValue()==='TW260800158','申报草稿刷新后保留');
  await page.getByRole('button',{name:'提交案例',exact:false}).click(); await snap();
  check((await page.locator('h1').innerText()).includes('0013'),'新案例生成唯一编号');
  await page.getByRole('textbox',{name:'案例回复'}).fill('原型验证：已补充测试结果。');
  await page.getByRole('button',{name:'发送',exact:true}).click(); await snap();
  check((await snap()).includes('原型验证：已补充测试结果。'),'案例留言保存并显示');
  await page.setViewportSize({width:390,height:844});
  await nav('dashboard'); await capture('16-mobile-customer');
  check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'手机客户首页没有横向溢出');
  await page.getByRole('button',{name:'申报售后案例',exact:true}).click(); await snap();
  check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'手机申报表单没有横向溢出');
  await page.getByRole('button',{name:'打开导航'}).click(); await snap();
  check(await page.locator('.sidebar').evaluate(el=>el.classList.contains('open')),'手机导航可展开');
  await page.keyboard.press('Escape');
  await page.setViewportSize({width:1440,height:1080});
  await nav('dashboard');
  await page.getByRole('button',{name:'原型导览',exact:true}).click(); await snap();
  await page.getByRole('button',{name:'恢复初始演示数据',exact:true}).click(); await snap();
  await page.getByRole('button',{name:'确认恢复',exact:true}).click(); await snap();
  check(await page.evaluate(()=>JSON.parse(localStorage.getItem('ebike-hifi-v1')).cases.length)===12,'验证后已恢复原始演示数据');
  check(errors.length===0,'流程验证期间无浏览器脚本错误');
  return results;
}
